remediation.command:
! Configure management lines to require login using the default or a named AAA authentication list. This configuration must be set individually for all line types.
line vty {line-number} [ending-line-number]
login authentication {default | aaa_list_name}

! Configure management lines to require login using the default or a named AAA authentication list. This configuration must be set individually for all line types.
ip http secure-server
ip http authentication {default | _aaa_list_name_}

! Bind AAA services to the loopback interface.
ip radius source-interface loopback {loopback_interface_number} or
aaa group server tacacs+ {group_name}
ip tacacs source-interface {loopback_interface_number}

! Configure the EIGRP address family key chain.
router eigrp <virtual-instance-name>
address-family ipv4 autonomous-system {eigrp_as-number}
af-interface {interface-name}
authentication key-chain {eigrp_key-chain_name}

! Configure the EIGRP address family authentication mode.
router eigrp <virtual-instance-name>
address-family ipv4 autonomous-system {eigrp_as-number}
af-interface {interface-name}
authentication mode md5

! Configure the interface with the EIGRP key chain.
interface {interface_name}
ip authentication key-chain eigrp {eigrp_as-number} {eigrp_key-chain_name}

! Configure the interface with the EIGRP authentication mode.
interface {interface_name}
ip authentication mode eigrp {eigrp_as-number} md5

! Configure at least one external NTP Server using the following commands
ntp server {ntp-server_ip_address} or
ntp server {ntp server vrf [vrf name] ip address}

! Disable proxy ARP on all interfaces.
interface {interface}
no ip proxy-arp

! Configure uRPF.
interface {interface_name}
ip verify unicast source reachable-via rx allow-default

! Apply the access-group for the external (untrusted) interface
interface {external_interface}
ip access-group {name | number} in

! Configure the EIGRP address family.
router eigrp <virtual-instance-name>
address-family ipv4 autonomous-system {eigrp_as-number}

! Configure the appropriate interface(s) for Message Digest authentication
interface {interface_name}
ip ospf message-digest-key {ospf_md5_key-id} md5 {ospf_md5_key}
